// GENERATED insignia — BOTH liveries live in the bundle as data URLs, so no
// stray deploy window can ever poison a separate image URL (the original sin
// this file was born from). The exports are LIVE BINDINGS: applyInsigniaDesign
// reassigns them in place when the admin switches the app's design, and every
// importer sees the new set on its next render without knowing why.
const CLASSIC = {
  NAV_PLAY: "data:image/webp;base64,",
  NAV_ARMY: "data:image/webp;base64,",
  NAV_ACH: "data:image/webp;base64,",
  NAV_PROFILE: "data:image/webp;base64,",
  IC_COIN: "data:image/webp;base64,",
  IC_SKILL: "data:image/webp;base64,",
  IC_SKULL: "data:image/webp;base64,",
  IC_CREST: "data:image/webp;base64,",
  IC_SPELLSTAR: "data:image/webp;base64,",
};
const CARVED = {
  NAV_PLAY: "data:image/webp;base64,",
  NAV_ARMY: "data:image/webp;base64,",
  NAV_ACH: "data:image/webp;base64,",
  NAV_PROFILE: "data:image/webp;base64,",
  IC_COIN: "data:image/webp;base64,",
  IC_SKILL: "data:image/webp;base64,",
  IC_SKULL: "data:image/webp;base64,",
  IC_CREST: "data:image/webp;base64,",
  IC_SPELLSTAR: "data:image/webp;base64,",
};
export let NAV_PLAY = CLASSIC.NAV_PLAY;
export let NAV_ARMY = CLASSIC.NAV_ARMY;
export let NAV_ACH = CLASSIC.NAV_ACH;
export let NAV_PROFILE = CLASSIC.NAV_PROFILE;
export let IC_COIN = CLASSIC.IC_COIN;
export let IC_SKILL = CLASSIC.IC_SKILL;
export let IC_SKULL = CLASSIC.IC_SKULL;
export let IC_CREST = CLASSIC.IC_CREST;
export let IC_SPELLSTAR = CLASSIC.IC_SPELLSTAR;
export function applyInsigniaDesign(design) {
  const S = design === "carved" ? CARVED : CLASSIC;
  NAV_PLAY = S.NAV_PLAY;
  NAV_ARMY = S.NAV_ARMY;
  NAV_ACH = S.NAV_ACH;
  NAV_PROFILE = S.NAV_PROFILE;
  IC_COIN = S.IC_COIN;
  IC_SKILL = S.IC_SKILL;
  IC_SKULL = S.IC_SKULL;
  IC_CREST = S.IC_CREST;
  IC_SPELLSTAR = S.IC_SPELLSTAR;
}
